import{t as e}from"./jsx-runtime-Cltr0gcK.js";var t={"q-family-1":{angle:`Walk the lobby`,teach:`Picture three doors. One parks in a fire. One waits for the fire brigade. One can be a way out. All three can say EN 81. The part number is which door you are standing at.`,prompt:`A brochure says only “EN 81”. What do you still not know?`,choices:[`Which part, and therefore which job the car does.`,`The paint colour.`,`Whether the building has stairs.`],answer:0},"q-family-2":{angle:`Factory, then the lab`,teach:`20 is the finished passenger elevator in the shaft. 50 is the sums and the tests on the pieces that went into it. 1 and 2 are the old pair those two replaced.`,prompt:`A new car still specified as EN 81-1 is…`,choices:[`Written to the retired base, not 20 with 50.`,`Automatically a firefighter elevator.`,`Exempt from LOLER.`],answer:0},"q-duty-1":{angle:`After the keys are handed over`,teach:`The manufacturer’s job ends when the elevator is allowed onto the market. After that, the responsible duty under LOLER sits with the owner or whoever controls the elevator. The fire brigade do not hold that duty.`,prompt:`Nine months with no thorough examination is whose problem?`,choices:[`The person who controls the elevator in use.`,`The passenger who rode it.`,`The standard that designed the buttons.`],answer:0},"q-duty-2":{angle:`The diary, not the brochure`,teach:`People-carrying elevators are usually examined every six months. A new evacuation car does not get a longer gap. Nine months is a late diary, even if the car is shiny.`,prompt:`Which clock is LOLER using for a passenger elevator?`,choices:[`About every six months, unless a written scheme says otherwise.`,`Once a year by default.`,`Only when the fire alarm is tested.`],answer:0},"q-20-1":{angle:`The everyday car`,teach:`20 is the car you ride to a meeting. It does not, by itself, park-and-stay (that is 73), wait for the fire brigade (72), or keep running as a way out (76). Those are extra parts stacked on top.`,prompt:`A wheelchair user in a fire needs which extra, not 20 alone?`,choices:[`An evacuation part such as EN 81-76, designed in.`,`A heavier rated load on the same 20 car.`,`A poster inside a standard car.`],answer:0},"q-20-2":{angle:`Two different test days`,teach:`50 is the integration half for a new elevator, beside 20. 80 is later, when an old elevator is still in a building and you are ranking what to fix. Same word “test”, different life stage.`,prompt:`EN 81-50 belongs with…`,choices:[`EN 81-20, on a new passenger elevator.`,`LOLER’s six-month visit.`,`A 1990 car you are trying to badge as 76.`],answer:0},"q-70-1":{angle:`Who fits in the car`,teach:`Type 2 is a wheelchair user plus someone with them: 1100 × 1400 mm, 630 kg, 900 mm door. Type 1 is the squeezed car for an old building that cannot give you that. A new building does not get to start at Type 1.`,prompt:`New building, first accessible car. You write…`,choices:[`Type 2 or larger.`,`Type 1, because it is the smallest in the table.`,`Whatever the architect left in the core.`],answer:0},"q-70-2":{angle:`The long car`,teach:`Type 3 is the longer one: 1100 × 2100 mm, 1000 kg. A wheelchair user, other people, and a stretcher can be the reason. It is also where Class B evacuation cars start.`,prompt:`A hospital wants a stretcher in the car. Which type is that story?`,choices:[`Type 3.`,`Type 1.`,`A goods-only hoist.`],answer:0},"q-70-3":{angle:`The marble problem`,teach:`Table 3 sizes are measured between the structural walls. Decoration may steal at most 15 mm. Forty millimetres of panelling is the lining eating the wheelchair.`,prompt:`Finishes take 40 mm off a Type 2 width. That car is…`,choices:[`No longer the size the table promised.`,`Fine, because finishes sit outside the rule.`,`Only wrong if the colour contrast is poor.`],answer:0},"q-73-1":{angle:`The trained dog`,teach:`Alarm. The standard car goes to the floor it was told, opens, and stops being an elevator. People who were in it get out. It does not keep collecting floors, and it does not turn into an evacuation car.`,prompt:`After a standard car has recalled, what should a landing call do?`,choices:[`Nothing useful — the car is out of normal service.`,`Bring it back up to sweep the fire floor.`,`Start automatic evacuation mode.`],answer:0},"q-73-2":{angle:`The poster and the hardware`,teach:`The poster is true for the ordinary car, because that car will park. A firefighter car and an evacuation car need different signs. One lobby with one message and three different machines is how someone boards the wrong door.`,prompt:`The “do not use the elevator” poster belongs, without extra words, on…`,choices:[`The standard car that will park.`,`Every door, including a signed 76 car.`,`Only the machine room.`],answer:0},"q-72-1":{angle:`Who holds the key`,teach:`This car is a tool. The fire brigade take it with their switch. It has a second supply and it is built to stay alive when water runs down the shaft. A passenger does not self-rescue in it by pressing a landing button.`,prompt:`After the alarm, a firefighter elevator is waiting for…`,choices:[`The fire service, under their control.`,`Any resident who can reach the button.`,`Goods pallets.`],answer:0},"q-72-2":{angle:`Same footprint, different job`,teach:`The smallest firefighter car is 1100 × 1400 mm, 630 kg, 800 mm door — the same sort of footprint as an accessible Type 2. The size does not make it an evacuation elevator. The key, the power and the water protection do.`,prompt:`A car the size of Type 2 is a firefighter elevator only if…`,choices:[`It is also built and controlled to EN 81-72.`,`The floor area matches, full stop.`,`Someone fits a larger mirror.`],answer:0},"q-72-3":{angle:`Two kinds of water`,teach:`Hose water in the shaft is expected, so the electrics are protected and the pit can drain. A sprinkler head in the well or the machine space is a shower on the controller. That one is not allowed.`,prompt:`Which water is the firefighter elevator designed around?`,choices:[`Firefighting water running in, not sprinklers over the gear.`,`Sprinklers in the well, to cool the car.`,`A flooded pit on purpose.`],answer:0},"q-76p-1":{angle:`The old wait`,teach:`For years the plan was a refuge and a wait. 76 is the first European standard that lets a new, specially built elevator be a way out for people who cannot use the stairs. It does not rewrite every passenger elevator.`,prompt:`76 changes the plan for whom?`,choices:[`People who cannot use the stairs, in a new elevator built for it.`,`Every existing passenger elevator from next year.`,`Goods elevators only.`],answer:0},"q-76p-2":{angle:`You cannot time-travel a car`,teach:`A 2018 elevator was built before 76 existed. Software and a sign do not make it that standard. You can improve an old car under the existing-elevator rules. You cannot re-date its birth.`,prompt:`A software patch on a 2018 car gives you…`,choices:[`A better old car, not an EN 81-76 elevator.`,`A full 76 evacuation elevator.`,`An exemption from the fire strategy.`],answer:0},"q-76p-3":{angle:`The event on the alarm panel`,teach:`76 is for a fire alarm and the orderly evacuation the strategy names. It steps aside for earthquake, flood, storm, explosion and chemical attack. If the well itself is on fire or full of water, this is not the way out.`,prompt:`Which event is inside 76’s job?`,choices:[`A fire alarm, with the landing still a safe place to wait.`,`The building flooding.`,`An earthquake.`],answer:0},"q-76c-1":{angle:`The simpler plot`,teach:`Class A is a lower building that does not already need a firefighter elevator, one way-out floor, no second power supply, no one driving it from a desk. Height and kit decide the class, not how disabled the occupants are.`,prompt:`A 40-storey tower that already needs a firefighter elevator is…`,choices:[`Not a Class A story.`,`Class A if the car is large.`,`Class A because it has a refuge.`],answer:0},"q-76c-2":{angle:`The fuller kit`,teach:`Class B brings a second power supply, a larger car, and the option of more than one exit floor and a person driving from outside the car. There is no remote desk on Class A.`,prompt:`You want someone in a control room to send the car. That is…`,choices:[`Class B.`,`Class A with a poster.`,`EN 81-73.`],answer:0},"q-76c-3":{angle:`Borrow the 70 table`,teach:`Class A starts at Type 2: wheelchair and a companion. Class B starts at Type 3 or Type 4, the longer or the turning car. 76 does not invent a new size table. It points at 70.`,prompt:`Class A, no stretcher. Minimum car?`,choices:[`Type 2.`,`Type 1.`,`No minimum.`],answer:0},"q-76m-1":{angle:`Two in the morning`,teach:`Automatic means you call the car and it takes you to the way-out floor. Nobody has to be awake to drive it. Driver and remote both need another person. Recall-and-park is the standard car giving up.`,prompt:`Independent self-rescue is which behaviour?`,choices:[`The car comes when you call and goes to the exit floor by itself.`,`A firefighter takes the key.`,`The car parks and opens at the designated floor.`],answer:0},"q-76m-2":{angle:`A staffed desk`,teach:`Remote means a person outside the car can see you, talk to you and send the car. That needs Class B, speech and video, and a human who is actually there. A phone in a drawer is not a mode.`,prompt:`Remote with nobody on the desk is…`,choices:[`A mode you have not really provided.`,`Still Class A automatic.`,`A firefighter elevator.`],answer:0},"q-76m-3":{angle:`The roster`,teach:`Driver-assisted is a trained person in the car, collecting people. A hospital that staffs the night can do that. A block of flats with no waking staff cannot. The mode has to match who is in the building.`,prompt:`Driver-assisted without a trained person on duty is…`,choices:[`A plan that fails when the alarm is real.`,`The same as automatic.`,`What Class A remote means.`],answer:0},"q-76b-1":{angle:`Can you leave the building?`,teach:`EEL means evacuation exit landing: the floor where the car stops and you can actually get outside. A floor you cannot leave is just another landing. Recall is supposed to aim at a real way out.`,prompt:`The car stops at a basement with no route to open air. That floor is…`,choices:[`Not an evacuation exit landing.`,`A valid EEL if the sign is green.`,`The machine room.`],answer:0},"q-76b-2":{angle:`The landing has turned`,teach:`Suspend service is the “stop, this way out is no longer safe” signal. The car goes to a landing that still has a safe route, and it comes out of evacuation service. It is not the celebration at the end, and it is not the fire brigade taking a 72 car.`,prompt:`Smoke fills the safe area. The evacuation car should…`,choices:[`Leave evacuation service and go to a landing that is still a way out.`,`Keep opening there so nobody waits.`,`Wait for the next LOLER visit.`],answer:0},"q-76b-3":{angle:`One minute`,teach:`When the supply changes, a Class B car has to be back in the evacuation within 60 seconds. A generator that “usually” starts after a few minutes is outside that sum. Evacuation does not pause for an engineer.`,prompt:`The standby supply takes four minutes. Against 76 that is…`,choices:[`Too slow. The limit is 60 seconds.`,`Fine, if it starts eventually.`,`A LOLER interval.`],answer:0},"q-76b-4":{angle:`The long drop between doors`,teach:`If two landing doors are more than 7 m apart, someone stuck between them needs a door into the shaft in the middle. Tall atriums and skipped floors are where this appears. It is not a spiral stair inside the well.`,prompt:`Landing doors 9 m apart on an evacuation elevator need…`,choices:[`An intermediate emergency evacuation door.`,`Nothing, if the car is Type 2.`,`A poster on each floor.`],answer:0},"q-28-1":{angle:`A person who knows the shaft`,teach:`The alarm is a conversation. The trapped person can talk both ways to a rescue service that can tell which elevator called, and it still works when the normal power has gone. A bell in the pit is not that.`,prompt:`The building is dark and someone is in the car. 28 still expects…`,choices:[`Two-way speech to a rescue service that can identify the elevator.`,`An email to facilities.`,`A light and no voice.`],answer:0},"q-28-2":{angle:`Assistance needs a voice`,teach:`Driver mode and remote mode both depend on another person. If they cannot hear you, they cannot assist. Remote also needs video. Automatic mode still needs the alarm for the moment the car simply stops.`,prompt:`Why does a remote evacuation car care about speech and video?`,choices:[`The person helping is not in the car with you.`,`It is only for hotel background music.`,`EN 81-71 wants a siren.`],answer:0},"q-ex-1":{angle:`An old car stays old`,teach:`A 1992 elevator is not pulled forward into 72 or 76. 80 is how you rank the safety gaps. 82 is how you improve access where the building will allow it. Pretending it is a new evacuation elevator is the dishonest move.`,prompt:`Honest starting pair for that 1992 car?`,choices:[`EN 81-80 and EN 81-82.`,`EN 81-76 and EN 81-72, applied backwards.`,`Leave it until it is replaced, with no look.`],answer:0},"q-ex-2":{angle:`New machine, old hole`,teach:`21 is for a new passenger elevator dropped into an existing building whose pit, headroom or well cannot meet 20. You add protection so the tight hole is still safe. It is not a way to badge an old controller as 76.`,prompt:`EN 81-21 shows up when…`,choices:[`The new elevator will not fit the clearances of an old building.`,`You want automatic evacuation on a 1990 panel.`,`You are writing a LOLER template.`],answer:0},"q-cmp-1":{angle:`Three manners, one alarm`,teach:`Same bell, three cars. The standard car parks and stays out of service. The firefighter car waits for the fire brigade. The evacuation car, if you specified one and the landing is still safe, keeps working for people who cannot use the stairs.`,prompt:`Which line is the right order: 73, then 72, then 76?`,choices:[`Parks. Fire brigade. Way out.`,`All three keep taking passenger calls.`,`72 parks, 76 is for goods, 73 is for stretchers.`],answer:0},"q-cmp-2":{angle:`Do not downgrade the fire brigade`,teach:`A tall building that needs a firefighter elevator does not get to swap it for a Class A evacuation car. Class A is the simpler building. 72 and 76 can both be needed. One does not delete the other.`,prompt:`Client: “Class A instead of the firefighter elevator.” You say…`,choices:[`No. That class is not for a building that must have 72. You may need both.`,`Yes. 76 replaces 72 everywhere.`,`Fit Type 1 and call it dual-use.`],answer:0},"q-cmp-3":{angle:`Nobody has to be free`,teach:`Self-rescue means the person leaves without waiting for a trained helper. That is automatic evacuation, not the firefighter’s key and not the standard car parking itself. An alarm button alone is not a way out.`,prompt:`Who can leave without a helper being free?`,choices:[`A person using automatic EN 81-76 operation.`,`A person in a standard car after 73 recall.`,`A person hoping the fire brigade take them.`],answer:0},"q-duty-3":{angle:`The mark is not the duty`,teach:`CE marking shows the elevator was allowed onto the market under the Lifts Directive. That is not the responsible duty. After handover, the responsible duty under LOLER, and the fire strategy, still apply. The mark does not make it a firefighter elevator or an evacuation elevator.`,prompt:`A new car has a CE mark. LOLER…`,choices:[`Still applies once people are riding it.`,`Never applies.`,`Only applies if the mark is missing.`],answer:0},"q-76p-4":{angle:`Plan B stays`,teach:`76 does not let you throw away the refuge and the evacuation chair. The standard refuses to cover the day the evacuation elevator itself is broken or unavailable. Elevators stop. The other aids are still the plan.`,prompt:`The new evacuation elevator is out of service. People who cannot use stairs…`,choices:[`Still need the aids and refuges the strategy kept.`,`Have no plan, because 76 replaced them.`,`Must use firefighter control instead, by default.`],answer:0},"q-76c-4":{angle:`No generator, still a way out`,teach:`Class A has no generator. If the power fails, the car must still move itself to the evacuation exit floor so people can leave. A car that stops between floors has not done that.`,prompt:`Mains fail on a Class A car. It should…`,choices:[`Move to the evacuation exit landing.`,`Wait in the shaft for an engineer.`,`Become a firefighter elevator.`],answer:0},"q-70-4":{angle:`No doorman`,teach:`A hinged door asks the wheelchair user to pull, hold and reverse. Automatic horizontal sliding doors do that work. Independent use includes the opening, not only the space inside the car.`,prompt:`Why not a heavy hinged landing door on an accessible car?`,choices:[`The person who needs the elevator cannot be the person who holds it.`,`Firefighters dislike the look.`,`EN 81-73 uses them to park.`],answer:0},"q-family-3":{angle:`A Tuesday, then a bad day`,teach:`70 is the extra on 20 for using the car on an ordinary day: space, doors, controls. 76 is the extra for leaving when the stairs are no good. 50 is the lab. 58 and 77 are other jobs.`,prompt:`Accessibility of a new passenger elevator, on a normal day, is…`,choices:[`EN 81-70.`,`EN 81-50.`,`EN 81-58.`],answer:0},"q-76b-5":{angle:`The place you wait`,teach:`The landing in front of an evacuation elevator has to be protected from fire and smoke, because that is where someone waits for the car. A green running-man in an ordinary corridor is not that. Floors the elevator does not serve can be shut off with fire doors or shutters instead.`,prompt:`A safe area fails when…`,choices:[`You cannot breathe there while you wait.`,`The artwork is missing.`,`It is not the machine room.`],answer:0}};function n(e){return t[e.id]??{angle:`Same fact, other door`,teach:e.plain,prompt:`Which line is the same rule, told from the landing?`,choices:[e.choices[e.answer],e.choices[(e.answer+1)%4],e.choices[(e.answer+2)%4]],answer:0}}var r=e(),i={"q-family-1":{src:`/graphics/ans2/q-family-1d.jpg`,alt:`Three different elevator doors in one lobby: a standard car, a firefighter car, and an evacuation car.`},"q-family-2":{src:`/graphics/ans2/q-family-2e.jpg`,alt:`A finished passenger car beside the safety parts that were tested before it was installed.`},"q-family-3":{src:`/graphics/ans2/q-family-3n.jpg`,alt:`Two dark vertical door panels face each other and part in the middle. They are a different colour from the wall. The panel is on the right-hand side wall.`},"q-duty-1":{src:`/graphics/ans2/q-duty-1.jpg`,alt:`Building keys and an examination diary on the desk of the person who controls the elevator.`},"q-duty-2":{src:`/graphics/ans2/q-duty-2b.jpg`,alt:`A six-month calendar beside an examination diary that is already overdue.`},"q-duty-3":{src:`/graphics/ans2/q-duty-3.jpg`,alt:`A new elevator nameplate next to the in-service examination diary that still has to be kept.`},"q-20-1":{src:`/graphics/ans2/q-20-1n.jpg`,alt:`A modern passenger elevator stopped at the lobby while a fire alarm glows. It is not a way out.`},"q-20-2":{src:`/graphics/ans2/q-20-2c.jpg`,alt:`Safety components on a test bench, the integration half that sits beside the finished car.`},"q-70-1":{src:`/graphics/ans2/q-70-1d.jpg`,alt:`A new-building elevator large enough for a wheelchair user and a companion, with a wide door.`},"q-70-2":{src:`/graphics/ans2/q-70-2m.jpg`,alt:`A long elevator car with room for a wheelchair user, other passengers, and a stretcher.`},"q-70-3":{src:`/graphics/ans2/q-70-3d.jpg`,alt:`Thick decorative wall panels inside an elevator, taking space away from the required car size.`},"q-70-4":{src:`/graphics/ans2/q-70-4o.jpg`,alt:`Power-operated sliding elevator doors open on their own, with nobody holding them.`},"q-73-1":{src:`/graphics/ans2/q-73-1o.jpg`,alt:`A standard elevator recalled to the exit floor, doors open, taken out of service during a fire alarm.`},"q-73-2":{src:`/graphics/ans2/q-73-2d.jpg`,alt:`A standard parked elevator beside a fire-instruction notice, unlike a specially signed evacuation car.`},"q-72-1":{src:`/graphics/ans2/q-72-1b.jpg`,alt:`A firefighter elevator with a key switch, waiting for the fire service, not for passengers.`},"q-72-2":{src:`/graphics/ans2/q-72-2b.jpg`,alt:`A basic firefighter car the size of an accessible Type 2 car, not a stretcher car.`},"q-72-3":{src:`/graphics/ans2/q-72-3b.jpg`,alt:`A dry firefighter shaft. Water is for the fire outside, not a sprinkler inside the well.`},"q-76p-1":{src:`/graphics/ans2/q-76p-1.jpg`,alt:`A specially built evacuation elevator open as a way out, not only a place to wait.`},"q-76p-2":{src:`/graphics/ans2/q-76p-2.jpg`,alt:`An older passenger elevator unchanged by a laptop. Software cannot turn it into an evacuation elevator.`},"q-76p-3":{src:`/graphics/ans2/q-76p-3o.jpg`,alt:`An evacuation elevator responding to a fire alarm, not to floodwater or a collapsed building.`},"q-76p-4":{src:`/graphics/ans2/q-76p-4.jpg`,alt:`An evacuation elevator with a refuge and an evacuation chair still in place as the backup.`},"q-76c-1":{src:`/graphics/ans2/q-76c-1.jpg`,alt:`A lower building with one exit to the street, no generator, and one evacuation elevator.`},"q-76c-2":{src:`/graphics/ans2/q-76c-2.jpg`,alt:`A Class B setup: a larger car, a generator, and a staffed control desk.`},"q-76c-3":{src:`/graphics/ans2/q-76c-3c.jpg`,alt:`A Class A car sized for a wheelchair user and a companion, next to a longer Class B car.`},"q-76c-4":{src:`/graphics/ans2/q-76c-4.jpg`,alt:`The mains have failed. With no generator, the car has still travelled to the exit floor and opened.`},"q-76m-1":{src:`/graphics/ans2/q-76m-1c.jpg`,alt:`An empty evacuation car with its own buttons, ready to run without a driver or a remote desk.`},"q-76m-2":{src:`/graphics/ans2/q-76m-2.jpg`,alt:`A staffed control desk with camera screens and a microphone linked to the elevator.`},"q-76m-3":{src:`/graphics/ans2/q-76m-3.jpg`,alt:`A simple drive control inside the elevator panel, for a trained person who is in the building.`},"q-76b-1":{src:`/graphics/ans2/q-76b-1n.jpg`,alt:`An elevator opening onto a lobby that leads straight out to fresh air.`},"q-76b-2":{src:`/graphics/ans2/q-76b-2.jpg`,alt:`An elevator leaving a smoke-filled landing and opening at a landing that is still safe.`},"q-76b-3":{src:`/graphics/ans2/q-76b-3.jpg`,alt:`Backup power bringing an evacuation elevator back into use within a minute.`},"q-76b-4":{src:`/graphics/ans2/q-76b-4q.jpg`,alt:`A tall gap between two landing doors, with an extra door into the shaft in between.`},"q-76b-5":{src:`/graphics/ans2/q-76b-5.jpg`,alt:`A protected lobby in front of an evacuation elevator, sealed so people can wait and breathe.`},"q-28-1":{src:`/graphics/ans2/q-28-1b.jpg`,alt:`An elevator alarm that opens a two-way call to a person who can answer.`},"q-28-2":{src:`/graphics/ans2/q-28-2.jpg`,alt:`Speech between the car and a person at a desk, so someone can actually assist.`},"q-reg-28":{src:`/graphics/ans2/q-reg-28.jpg`,alt:`The passenger autodialer in the car, separate from the firefighter telephone.`},"q-ex-1":{src:`/graphics/ans2/q-ex-1c.jpg`,alt:`An old small elevator being assessed for real hazards, not relabelled as a new evacuation car.`},"q-ex-2":{src:`/graphics/ans2/q-ex-2.jpg`,alt:`A new elevator fitted into an older, tighter shaft, with extra protection where space is missing.`},"q-cmp-1":{src:`/graphics/ans2/q-cmp-1f.jpg`,alt:`Three cars on one alarm: one parked, one waiting for the fire brigade, one still working as a way out.`},"q-cmp-2":{src:`/graphics/ans2/q-cmp-2.jpg`,alt:`A firefighter elevator and an evacuation elevator side by side. One does not replace the other.`},"q-cmp-3":{src:`/graphics/ans2/q-cmp-3.jpg`,alt:`An evacuation elevator open at the exit so a person can leave without waiting for a helper.`},"q-reg-puwer":{src:`/graphics/ans2/q-reg-puwer.jpg`,alt:`An examination diary and maintenance tools together. LOLER does not cancel the duty to maintain work equipment.`},"q-reg-fire":{src:`/graphics/ans2/q-reg-fire.jpg`,alt:`A Scottish block of flats whose fire duty is the Scottish fire law, not the English order.`},"q-reg-eq":{src:`/graphics/ans2/q-reg-eq.jpg`,alt:`An office elevator standing out of service, the only way up to the meeting rooms.`},"q-reg-riddor":{src:`/graphics/ans2/q-reg-riddor.jpg`,alt:`Someone has left an elevator unhurt. The report book stays closed because not every incident is reportable.`},"q-reg-mach":{src:`/graphics/ans2/q-reg-machl.jpg`,alt:`A stairlift and a slow vertical platform, placed on the market as machinery rather than as a lift.`},"q-reg-cdm":{src:`/graphics/ans2/q-reg-cdmb.jpg`,alt:`A pit designed with a way out, so the danger is removed on the drawing rather than left to the work method.`},"q-reg-wah":{src:`/graphics/ans2/q-reg-wah.jpg`,alt:`A car top prepared for work, with the elevator locked so it cannot move under the person.`}},a={src:`/graphics/practice-20-2.jpg`,alt:`A passenger elevator in its shaft.`};function o({questionId:e}){let t=i[e]??a;return(0,r.jsx)(`figure`,{className:`mx-auto max-w-md overflow-hidden rounded-xl bg-night text-night-fg shadow-[var(--shadow-border)]`,children:(0,r.jsx)(`img`,{src:t.src,alt:t.alt,className:`aspect-video w-full object-cover`})})}export{n,o as t};